fig\n                end\n            end\n            config = config or {}\n\n            pcall(function()\n                originalNotify(NexusLib, config)\n            end)\n        end\n    end\nend\n\n-- ============================================================\n-- ===== NEXUS USERS PROTECTION (ANTI-REPORT) =====\n-- ============================================================\ndo\n    pcall(function()\n        LocalPlayer:SetAttribute("NexusUser", true)\n        if LocalPlayer.Character then\n            LocalPlayer.Character:SetAttribute("NexusUser", true)\n        end\n        LocalPlayer.CharacterAdded:Connect(function(char)\n            pcall(function()\n                LocalPlayer:SetAttribute("NexusUser", true)\n                char:SetAttribute("NexusUser", true)\n            end)\n        end)\n    end)\n\n    pcall(function()\n        if hookmetamethod and not _G.NexusNamecallHooked then\n            _G.NexusNamecallHooked = true\n            local oldNamecall\n            oldNamecall = hookmetamethod(game, "__namecall", function(self, ...)\n                local method = getnamecallmethod()\n                if (method == "ReportAbuse" or method == "reportAbuse") and self == Players then\n                    local args = {...}\n                    local target = args[1]\n                    local isNexusUser = false\n                    if typeof and typeof(target) == "Instance" then\n                        if typeof(target) == "Instance" and typeof(target) == "Instance" and target:IsA("Player") then\n                            if target:GetAttribute("NexusUser") or (target.Character and target.Character:GetAttribute("NexusUser")) then\n                                isNexusUser = true\n                            end\n                        end\n                    elseif type(target) == "string" then\n                        local p = Players:FindFirstChild(target)\n                        if p and (p:GetAttribute("NexusUser") or (p.Character and p.Character:GetAttribute("NexusUser"))) then\n                            isNexusUser = true\n                        end\n                    end\n                    if isNexusUser and NexusState.antiReportEnabled ~= false then\n                        NexusLib:Notify({\n                            Title = "Nexus Shield",\n                            Message = "You cannot report another Nexus Hub user!",\n                            Duration = 3\n                        })\n                        return nil\n                    end\n                end\n                return oldNamecall(self, ...)\n            end)\n        end\n    end)\nend\n\n-- ============================================================\n-- ===== AUTO LANGUAGE (I18N) =====\n-- ============================================================\nlocal I18n = {}\ndo\n    local LocalizationService = Services.LocalizationService or game:GetService("LocalizationService")\n    local rawLocale = "en"\n    pcall(function()\n        rawLocale = string.lower(\n            LocalizationService.RobloxLocaleId \n            or LocalizationService.SystemLocaleId \n            or (LocalizationService.GetRobloxLocaleId and LocalizationService:GetRobloxLocaleId()) \n            or (LocalizationService.GetSystemLocaleId and LocalizationService:GetSystemLocaleId()) \n            or "en"\n        )\n    end)\n\n    local autoLang = "en"\n    if string.find(rawLocale, "^th") then\n        autoLang = "th"\n    elseif string.find(rawLocale, "^id") then\n        autoLang = "id"\n    elseif string.find(rawLocale, "^es") then\n        autoLang = "es"\n    elseif string.find(rawLocale, "^pt") then\n        autoLang = "pt"\n    elseif string.find(rawLocale, "^zh") then\n        autoLang = "zh"\n    elseif string.find(rawLocale, "^ru") then\n        autoLang = "ru"\n    end\n\n    NexusState.detectedLanguage = autoLang\n\n    local DICTIONARY = {\n        es = {\n            ["Session"] = "Sesi\u{F3}n",\n            ["Routine"] = "Pesca",\n            ["Shop"] = "Tienda",\n            ["Exchange"] = "Intercambio",\n            ["Quests"] = "Misiones",\n            ["Upgrade"] = "Mejoras",\n            ["Teleport"] = "Teletransporte",\n            ["Settings"] = "Ajustes",\n            ["Session overview"] = "Resumen de la sesi\u{F3}n",\n            ["Release notes"] = "Notas de la versi\u{F3}n",\n            ["Fishing routine"] = "Rutina de pesca",\n            ["Farm On Weather Section"] = "Auto Farm por Clima",\n            ["Skill profile"] = "Perfil de habilidades",\n            ["Auto Equip"] = "Auto Equipar",\n            ["Auto Nameless Octoparasite"] = "Auto Pulpo Sin Nombre",\n            ["Auto Favorite Fish"] = "Auto Favorito de Peces",\n            ["Auto Pray Spirit"] = "Auto Rezar al Esp\u{ED}ritu",\n            ["Auto Farm"] = "Auto Farm",\n            ["Index"] = "\u{CD}ndice de Peces",\n            ["Upgrade Skill"] = "Mejorar Habilidad",\n            ["Craft Rod"] = "Fabricar Ca\u{F1}a",\n            ["Auto Buy Bait"] = "Auto Comprar Cebo",\n            ["Auto Buy Rod"] = "Auto Comprar Ca\u{F1}a",\n            ["Learn Skills"] = "Aprender Habilidades",\n            ["Trait Reroll"] = "Reroll de Rasgos",\n            ["Craft Bait"] = "Fabricar Cebo",\n            ["Auto Gacha"] = "Auto Gacha",\n            ["Exchange Items"] = "Intercambiar Objetos",\n            ["Auto Claim Ticket Quest"] = "Auto Reclamar Misi\u{F3}n Ticket",\n            ["Daily Quests"] = "Misiones Diarias",\n            ["Material Farming"] = "Farm de Materiales",\n            ["Auto Do Ticket Quest"] = "Auto Hacer Misi\u{F3}n Ticket",\n            ["Character Upgrade"] = "Mejorar Personaje",\n            ["Character"] = "Personaje",\n            ["World & Misc"] = "Mundo y Varios",\n            ["Streamer Mode (Fake Name)"] = "Modo Streamer (Nombre Falso)",\n            ["Language & Localization"] = "Idioma y Localizaci\u{F3}n",\n            ["Nexus Shield"] = "Escudo Nexus",\n            ["Staff Watch"] = "Vigilancia de Staff",\n            ["ESP"] = "ESP",\n            ["Lock catch bar"] = "Bloquear barra de captura",\n            ["Auto C         task.wait(0.2)\n            teleportBack()\n        end\n    end\n\n    task.spawn(function()\n        while task.wait(2) do\n            if not alive() then break end\n            pcall(doSell)\n        end\n    end)\nend\n\nif runtimeEnv.NexusMinigameConn then pcall(function() runtimeEnv.NexusMinigameConn:Disconnect() end) end\nruntimeEnv.NexusMinigameConn = Events.FishingMinigame.OnClientEvent:Connect(function(p1, p2, p3)\n    if not p1 or not p2 then return end\n    Fishing.BossFarm.CurrentTarget = p1\n    Fishing.BossFarm.CurrentToken = p3\n    Fishing.BossFarm.HasHooked = true\n    Fishing.BossFarm.PendingCancel = false\n    Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n    local runId = Fishing.BossFarm.CurrentRunId\n    local target = getCurrentHookTarget()\n    local shouldFarm = shouldFarmBossTarget(target)\n    if bossFarmEnabled() and not shouldFarm then\n        Fishing.BossFarm.PendingCancel = true\n        task.delay(0.15, cancelOrReleaseNormalFish)\n        return\n    end\n    if Fishing.Flags.AutoCast or (bossFarmEnabled() and shouldFarm) then\n        task.spawn(function()\n            local minigameActive = true\n            local connection\n            local fishingGui = MainGui:FindFirstChild("Fishing")\n            if fishingGui then\n                connection = fishingGui:GetPropertyChangedSignal("Visible"):Connect(function()\n                    if not fishingGui.Visible then\n                        minigameActive = false\n                        if connection then connection:Disconnect() connection = nil end\n                    end\n                end)\n            end\n            while minigameActive do\n                if not alive() then break end\n                if not MainGui:FindFirstChild("Fishing") or not MainGui.Fishing.Visible then break end\n                if bossFarmEnabled() then\n                    if runId ~= Fishing.BossFarm.CurrentRunId then break end\n                    target = getCurrentHookTarget()\n                    shouldFarm = shouldFarmBossTarget(target)\n                    if not shouldFarm then\n                        Fishing.BossFarm.PendingCancel = true\n                        cancelOrReleaseNormalFish()\n                        break\n                    end\n                    farmHookedBoss(target)\n                    task.wait(0.08)\n                else\n                    pcall(function() Events.UpdateFishProgression:FireServer() end)\n                    task.wait(0.2)\n                end\n            end\n            if connection then pcall(function() connection:Disconnect() end) connection = nil end\n            if bossFarmEnabled() and runId == Fishing.BossFarm.CurrentRunId then\n                resetBossFarmTarget()\n            end\n        end)\n    end\nend)\n\nif runtimeEnv.NexusSlamConn then pcall(function() runtimeEnv.NexusSlamConn:Disconnect() end) end\nruntimeEnv.NexusSlamConn = Events.Slam.OnClientEvent:Connect(function(cb)\n    if Fishing.Flags.MainFarm then\n        task.spawn(function()\n            task.wait(0.1)\n            pcall(function() cb:FireServer("Perfect") end)\n            local tc = MainGui:FindFirstChild("Fishing") and MainGui.Fishing:FindFirstChild("TrashCan")\n            if tc and tc:FindFirstChild("Slam") then tc.Slam:Destroy() end\n        end)\n    end\nend)\n\n-- GUI click QTE (Rewritten Auto Enzo)\nlocal prevBarPos = 0\nlocal lastFrameTime = tick()\nlocal currentSpeed = 0\nlocal lastQTEClick = 0\nlocal lastQTEHitboxX = nil\n\n-- Click QTE the same way the game listens: desktop Fishing GUI button\n-- first (Fishing2.MouseButton1Down path), then mobile button, then\n-- synthetic mouse input as last fallback. Never fires blind.\nlocal EnzoQTEGui = nil\nlocal function findEnzoQTEGui()\n    if EnzoQTEGui and EnzoQTEGui.Parent then return EnzoQTEGui end\n    EnzoQTEGui = nil\n    local fishing = MainGui:FindFirstChild("Fishing")\n    local btn = fishing and (fishing:FindFirstChild("Fishing2") or fishing:FindFirstChild("Button"))\n    if btn and typeof(btn) == "Instance" and btn:IsA("GuiButton") then EnzoQTEGui = btn return btn end\n    local mobileFishing = MainGui:FindFirstChild("Mobile") and MainGui.Mobile:FindFirstChild("Fishing")\n    local mbtn = mobileFishing and (mobileFishing:FindFirstChild("Button") or mobileFishing)\n    if mbtn and typeof(mbtn) == "Instance" and mbtn:IsA("GuiButton") then EnzoQTEGui = mbtn return mbtn end\n    if fishing and typeof(fishing) == "Instance" and fishing:IsA("GuiButton") then EnzoQTEGui = fishing return fishing end\n    return nil\nend\n\nlocal function pressEnzoQTE()\n    local btn = findEnzoQTEGui()\n    if btn and firesignal then\n        pcall(firesignal, btn.MouseButton1Down)\n        return\n    end\n    pcall(function()\n        local vim = game:GetService("VirtualInputManager")\n        vim:SendMouseButtonEvent(0, 0, 0, true, game, 0)\n        vim:SendMouseButtonEvent(0, 0, 0, false, game, 0)\n    end)\nend\n\nlocal renderAccum = 0\nlocal RENDER_THROTTLE = 0.033\nlocal cachedFishingGui = nil\nlocal cachedBossBar = nil\n\nlocal function updateFrameLogic(dt)\n    if not cachedFishingGui or not cachedFishingGui.Parent then\n        cachedFishingGui = MainGui and MainGui:FindFirstChild("Fishing")\n        cachedBossBar = cachedFishingGui and cachedFishingGui:FindFirstChild("BossFightBar")\n    end\n    local fishing = cachedFishingGui\n    local bossBar = cachedBossBar\n    local bossBarVisible = bossBar ~= nil and bossBar.Visible == true\n    local fishingVisible = fishing ~= nil and fishing.Visible == true\n\n    if not bossBarVisible then\n        renderAccum = renderAccum + dt\n        if renderAccum < RENDER_THROTTLE then return end\n        renderAccum = 0\n    end\n\n    if (Fishing.Flags.AnchorLock or Fishing.Flags.AutoSkillCheck or Fishing.Flags.AutoLongDiaohai) and fishingVisible then\n        if Fishing.Flags.AnchorLock and not bossBarVisible and not Fishing.BossFarm.PendingCancel then\n            local bf = fishing:FindFirstChild("BarFrame")\n            local b = bf and bf:FindFirstChild("Bar")\n            if b then b.Position = UDim2.new(0.5, 0, 0.5, 0) end\n        end\n\n        if (Fishing.Flags.AutoSkillCheck or Fishing.Flags.AutoLongDiaohai) and bossBarVisible then\n            local bar = bossBar:FindFirstChild("Bar")\n            local hitbox = bossBar:FindFirstChild("Hitbox")\n            local badHitbox = bossBar:FindFirstChild("HitboxBad")\n            if bar and hitbox and hitbox.Visible then\n                local barPos = bar.Position.X.Scale\n                local hbPos = hitbox.Position.X.Scale - hitbox.Size.X.Scale * hitbox.AnchorPoint.X\n                local hbSize = hitbox.Size.X.Scale\n                if lastQTEHitboxX ~= hbPos then\n                    lastQTEHitboxX = hbPos\n                    lastQTEClick = 0\n                end\n\n                local now = tick()\n                local dtFrame = now - lastFrameTime\n                lastFrameTime = now\n\n                if dtFrame > 0.001 and dtFrame < 0.1 then\n                    local rawSpeed = (barPos - prevBarPos) / dtFrame\n                    prevBarPos = barPos\n                    if math.abs(rawSpeed) < 5 then\n                        currentSpeed = currentSpeed * 0.7 + rawSpeed * 0.3\n                    end\n                else\n                    prevBarPos = barPos\n                end\n\n                local lastInput = UserInputService:GetLastInputType()\n                local latency = (lastInput == Enum.UserInputType.Touch) and 0.06 or 0.025\n                local compensatedBarPos = barPos - (currentSpeed * latency)\n\n                local margin = hbSize * 0.15\n                local badOverlap = false\n                if badHitbox and badHitbox.Visible then\n                    local badLeft = badHitbox.Position.X.Scale - badHitbox.Size.X.Scale * badHitbox.AnchorPoint.X\n                    badOverlap = compensatedBarPos >= badLeft and compensatedBarPos <= badLeft + badHitbox.Size.X.Scale\n                end\n\n                if not badOverlap and compensatedBarPos >= hbPos + margin and compensatedBarPos <= hbPos + hbSize - margin then\n                    if tick() - lastQTEClick > 0.15 then\n                        lastQTEClick = tick()\n                        pressEnzoQTE()\n                    end\n                end\n            else\n                lastQTEHitboxX = nil\n                prevBarPos = 0\n                lastFrameTime = tick()\n                currentSpeed = 0\n            end\n        else\n            lastQTEHitboxX = nil\n            prevBarPos = 0\n            lastFrameTime = tick()\n            currentSpeed = 0\n        end\n    end\n\n    if NexusState.flying and NexusState.bg and NexusState.bv and LocalPlayer.Character then\n        local h = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")\n        local hum = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")\n        if h and hum then\n            local cameraLook = Camera.CFrame.LookVector\n            local move = hum.MoveDirection\n            local horizontal = Vector3.new(move.X, 0, move.Z)\n            local vertical = (NexusState.flyKeys.Up and 1 or 0) - (NexusState.flyKeys.Down and 1 or 0)\n            NexusState.bv.Velocity = horizontal * NexusState.flySpeed + Vector3.new(0, vertical * NexusState.flySpeed, 0)\n            local look = Vector3.new(cameraLook.X, 0, cameraLook.Z)\n            if look.Magnitude > 0.01 then\n                NexusState.bg.CFrame = CFrame.lookAt(h.Position, h.Position + look.Unit)\n            end\n        end\n    end\n\n    if MiscFlags.FullBright then\n        if not NexusState.fullBrightApplied then\n            Lighting.Ambient = Color3.new(1,1,1)\n            Lighting.ColorShift_Bottom = Color3.new(1,1,1)\n            Lighting.ColorShift_Top = Color3.new(1,1,1)\n            Lighting.Brightness = 2\n            Lighting.OutdoorAmbient = Color3.new(1,1,1)\n            NexusState.fullBrightApplied = true\n        end\n    else\n        if NexusState.fullBrightApplied then\n            NexusState.fullBrightApplied = false\n        end\n    end\nend\n\nruntimeEnv.NexusFrameConnection = RunService.RenderStepped:Connect(function(dt)\n    if not alive() then return end\n    pcall(updateFrameLogic, dt)\nend)\n\n-- ============================================================\n-- ===== PREPARE GLOBALS FOR THE CHUNKS =====\n-- ============================================================\n_G.RunService = RunService\n_G.LocalPlayer = LocalPlayer\n_G.VirtualUser = VirtualUser\n_G.UserInputService = UserInputService\n_G.Events = Events\n_G.MiscFlags = MiscFlags\n_G.alive = alive\n_G.runtimeEnv = runtimeEnv\n_G.Players = Players\n_G.Workspace = Workspace\n_G.Lighting = Lighting\n_G.NexusState = NexusState\n_G.Fishing = Fishing\n\n-- ===== LIVE ANTI-AFK (main chunk; fires only on real Idled, never steals controller) =====\ndo\n    local function nexusNudgeInput()\n        if Fishing and Fishing.Flags and not Fishing.Flags.AntiAFK then return end\n        local moving = false\n        pcall(function()\n            local char = LocalPlayer.Character\n            local hum = char and char:FindFirstChildOfClass("Humanoid")\n            local md = hum and hum.MoveDirection\n            if md and (math.abs(md.X or 0) + math.abs(md.Z or 0) > 0.05) then moving = true end\n        end)\n        if moving then return end\n        pcall(function()\n            if Events and Events:FindFirstChild("AFK") then\n                Events.AFK:FireServer()\n            end\n            if VirtualUser and workspace.CurrentCamera then\n                VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                task.wait(0.2)\n                VirtualUser:Button2Up(Vector2.new(0, 0), works