pc = Workspace:FindFirstChild("NPC")\n                    if npc then\n                        local learnSkill = npc:FindFirstChild("LearnSkill")\n                        if learnSkill then\n                            local sageYijiu = learnSkill:FindFirstChild("Sage Yijiu")\n                            if typeof(sageYijiu) == "Instance" and sageYijiu:IsA("Model") then\n                                local hrp = sageYijiu:FindFirstChild("HumanoidRootPart")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            NexusState.learnSkill.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.learnSkill.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.learnSkill.teleported then\n                        NexusLib:Notify({ Title = "Learn Skills", Message = "Could not find Sage Yijiu, teleport failed. Continuing anyway.", Duration = 3 })\n                    end\n                end\n                local learnedCount = 0\n                for _, skillName in ipairs(selectedLearnSkills) do\n                    local success, err = pcall(function()\n                        Events.BuySkill:FireServer(skillName)\n                    end)\n                    if success then\n                        learnedCount = learnedCount + 1\n                        NexusLib:Notify({ Title = "Learn Skills", Message = "Learned " .. skillName, Duration = 2 })\n                    else\n                        NexusLib:Notify({ Title = "Learn Skills", Message = "Failed to learn " .. skillName .. ": " .. tostring(err), Duration = 2 })\n                    end\n                    task.wait(0.3)\n                end\n                if NexusState.learnSkill.teleported and NexusState.learnSkill.oldPosition then\n                    task.wait(0.2)\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild("HumanoidRootPart")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.learnSkill.oldPosition)\n                            NexusState.learnSkill.oldPosition = nil\n                            NexusState.learnSkill.teleported = false\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = "Learn Skills", Message = "Learned " .. learnedCount .. " skill(s)!", Duration = 3 })\n            end\n        })\n    end\n\n    -- Trait Reroll\n    do\n        local TraitSection = ShopTab:CreateSection("Trait Reroll")\n        local function GetOwnedSkillNames()\n            local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not p then return {"No skill owned"} end\n            local skills = {}\n            for _, f in pairs(p.Skill:GetChildren()) do\n                if typeof(f) == "Instance" and typeof(f) == "Instance" and f:IsA("Folder") and f.Owned and f.Owned.Value == true then\n                    table.insert(skills, f.Name)\n                end\n            end\n            if #skills == 0 then return {"No skill owned"} end\n            return skills\n        end\n\n        local function GetTraitNames()\n            local traits = {}\n            if not Info or not Info:FindFirstChild("Trait") then return {"No trait available"} end\n            for _, child in pairs(Info.Trait:GetChildren()) do\n                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("ModuleScript") then\n                    local ok, mod = pcall(require, child)\n                    if ok and type(mod) == "table" and mod.Name then\n                        table.insert(traits, mod.Name)\n                    end\n                end\n            end\n            if #traits == 0 then return {"No trait available"} end\n            return traits\n        end\n\n        local ownedSkills = GetOwnedSkillNames()\n        local selectedSkillForReroll = ownedSkills[1] or "No skill owned"\n        local traitNames = GetTraitNames()\n        local selectedTargetTrait = traitNames[1] or "No trait available"\n        local ignoreLocked = false\n\n        local traitSkillDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap("Dropdown", "Select Skill", {\n            Name = "Select Skill",\n            Options = ownedSkills,\n            Default = selectedSkillForReroll,\n            Callback = function(value) selectedSkillForReroll = value end\n        })), "Dropdown", "Select Skill", {\n            Name = "Select Skill",\n            Options = ownedSkills,\n            Default = selectedSkillForReroll,\n            Callback = function(value) selectedSkillForReroll = value end\n        })\n\n        local targetTraitDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap("Dropdown", "Target Trait", {\n            Name = "Target Trait",\n            Options = traitNames,\n            Default = selectedTargetTrait,\n            Callback = function(value) selectedTargetTrait = value end\n        })), "Dropdown", "Target Trait", {\n            Name = "Target Trait",\n            Options = traitNames,\n            Default = selectedTargetTrait,\n            Callback = function(value) selectedTargetTrait = value end\n        })\n\n        local ignoreLockedToggle = Cfg.register(TraitSection:CreateToggle(Cfg.wrap("Toggle", "Ignore Locked", {\n            Name = "Ignore Locked",\n            Default = false,\n            Callback = function(value) ignoreLocked = value end\n        })), "Toggle", "Ignore Locked", {\n            Name = "Ignore Locked",\n            Default = false,\n            Callback = function(value) ignoreLocked = value end\n        })\n\n        local rerollMethodDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap("Dropdown", "Reroll Method", {\n            Name = "Reroll Method",\n            Options = {"Instant", "Teleport"},\n            Default = NexusState.Reroll.method or "Instant",\n            Callback = function(value) NexusState.Reroll.method = value end\n        })), "Dropdown", "Reroll Method", {\n            Name = "Reroll Method",\n            Options = {"Instant", "Teleport"},\n            Default = NexusState.Reroll.method or "Instant",\n            Callback = function(value) NexusState.Reroll.method = value end\n        })\n\n        local RerollTrait = Events:FindFirstChild("RerollTrait")\n\n        TraitSection:CreateButton({\n            Name = "Reroll Until Trait",\n            Callback = function()\n                if NexusState.Reroll.running then\n                    NexusState.Reroll.running = false\n                    if NexusState.Reroll.thread then\n                        task.cancel(NexusState.Reroll.thread)\n                        NexusState.Reroll.thread = nil\n                    end\n                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then\n                        local char = LocalPlayer.Character\n                        if char then\n                            local root = char:FindFirstChild("HumanoidRootPart")\n                            if root then\n                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)\n                                NexusState.Reroll.oldPosition = nil\n                                NexusState.Reroll.teleported = false\n                            end\n                        end\n                    end\n                    NexusLib:Notify({ Title = "Reroll", Message = "Stopped", Duration = 2 })\n                    return\n                end\n\n                local skillName = selectedSkillForReroll\n                local targetTrait = selectedTargetTrait\n                if not skillName or skillName == "" or skillName == "No skill owned" then\n                    NexusLib:Notify({ Title = "Reroll", Message = "Select a valid skill", Duration = 2 })\n                    return\n                end\n                if not targetTrait or targetTrait == "" or targetTrait == "No trait available" then\n                    NexusLib:Notify({ Title = "Reroll", Message = "Select a target trait", Duration = 2 })\n                    return\n                end\n                if not RerollTrait then\n                    NexusLib:Notify({ Title = "Reroll", Message = "RerollTrait event not found", Duration = 2 })\n                    return\n                end\n                local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                local rerollCount = p and p:FindFirstChild("Trait Reroll")\n                if rerollCount and rerollCount.Value <= 0 then\n                    NexusLib:Notify({ Title = "Reroll", Message = "No rerolls left!", Duration = 2 })\n                    return\n                end\n\n                NexusState.Reroll.teleported = false\n                NexusState.Reroll.oldPosition = nil\n                if NexusState.Reroll.method == "Teleport" then\n                    local npc = Workspace:FindFirstChild("NPC")\n                    if npc then\n                        local func = npc:FindFirstChild("Function")\n                        if func then\n                            local nanjiang = func:FindFirstChild("Nanjiang")\n                            if typeof(nanjiang) == "Instance" and nanjiang:IsA("ModelirstChild("Head")\n            if not head then return end\n            local billboard = head:FindFirstChild("EspBillboard")\n            if billboard then billboard:Destroy() end\n            for i, conn in ipairs(espConnections) do\n                if conn.player == player then\n                    table.remove(espConnections, i)\n                    break\n                end\n            end\n        end\n        \n        local function clearAllEsp()\n            for _, conn in ipairs(espConnections) do\n                pcall(function()\n                    if conn.billboard and conn.billboard.Parent then\n                        conn.billboard:Destroy()\n                    end\n                end)\n            end\n            espConnections = {}\n        end\n        \n        local function updateAllEsp()\n            if not espEnabled then return end\n            clearAllEsp()\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    pcall(function() createEspForPlayer(player) end)\n                end\n            end\n        end\n        \n        local function startEsp()\n            if espEnabled then return end\n            espEnabled = true\n            updateAllEsp()\n            \n            local playerAddedConn = Players.PlayerAdded:Connect(function(player)\n                if espEnabled then\n                    task.wait(0.5)\n                    pcall(function() createEspForPlayer(player) end)\n                end\n            end)\n            table.insert(espConnections, { conn = playerAddedConn })\n            \n            local playerRemovingConn = Players.PlayerRemoving:Connect(function(player)\n                pcall(function() removeEspForPlayer(player) end)\n            end)\n            table.insert(espConnections, { conn = playerRemovingConn })\n            \n            local characterAddedConn = Players.PlayerAdded:Connect(function(player)\n                if espEnabled then\n                    player.CharacterAdded:Connect(function()\n                        task.wait(0.5)\n                        pcall(function() createEspForPlayer(player) end)\n                    end)\n                end\n            end)\n            table.insert(espConnections, { conn = characterAddedConn })\n            \n            espThread = task.spawn(function()\n                while espEnabled do\n                    task.wait(10)\n                    if espEnabled then\n                        pcall(updateAllEsp)\n                    end\n                end\n            end)\n            \n            NexusLib:Notify({ Title = "ESP", Message = "Players ESP enabled!", Duration = 2 })\n        end\n        \n        local function stopEsp()\n            espEnabled = false\n            if espThread then\n                task.cancel(espThread)\n                espThread = nil\n            end\n            clearAllEsp()\n            for _, conn in ipairs(espConnections) do\n                if conn.conn then\n                    pcall(function() conn.conn:Disconnect() end)\n                end\n            end\n            espConnections = {}\n            NexusLib:Notify({ Title = "ESP", Message = "Players ESP disabled!", Duration = 2 })\n        end\n        \n        Cfg.register(EspSection:CreateToggle(Cfg.wrap("Toggle", "Players", {\n            Name = "Players",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startEsp()\n                else\n                    stopEsp()\n                end\n            end\n        })), "Toggle", "Players", {\n            Name = "Players",\n            Default = false,\n            Callback = function(value)\n                if value then\n                    startEsp()\n                else\n                    stopEsp()\n                end\n            end\n        })\n        \n        -- ===== BOAT ESP =====\n        do\n            local boatEspEnabled = false\n            local boatEspThread = nil\n            local boatEspHighlights = {}\n            local boatFolder = workspace:FindFirstChild("Boat")\n            \n            local function createBoatEsp(boatModel)\n                if not boatModel or typeof(boatModel) ~= "Instance" or not boatModel:IsA("Model") then return end\n                if boatEspHighlights[boatModel] then return end\n                \n                -- Only handle it when the parent is a Folder\n                if not boatModel.Parent or typeof(boatModel.Parent) ~= "Instance" or not boatModel.Parent:IsA("Folder") then return end\n                \n                local attachPart = boatModel:FindFirstChildWhichIsA("BasePart")\n                if not attachPart then\n                    attachPart = boatModel:FindFirstChildWhichIsA("BasePart", true)\n                end\n                if not attachPart then return end\n                \n                local parentName = "Boat"\n                local parent = boatModel.Parent\n                if parent and parent ~= boatFolder then\n                    parentName = parent.Name\n                end\n                \n                local highlight = Instance.new("Highlight")\n                highlight.FillColor = Color3.fromRGB(0, 150, 255)\n                highlight.FillTransparency = 0.5\n                highlight.OutlineColor = Color3.fromRGB(0, 255, 255)\n                highlight.OutlineTransparency = 0.3\n                highlight.Adornee = boatModel\n                highlight.Parent = boatModel\n                \n                local billboard = Instance.new("BillboardGui")\n                billboard.Name = "BoatEspBillboard"\n                billboard.Size = UDim2.new(0, 150, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new("Frame")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new("UICorner")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new("TextLabel")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(0, 0, 255)\n                label.Text = "Boat | " .. parentName\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                boatEspHighlights[boatModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeBoatEsp(boatModel)\n                local data = boatEspHighlights[boatModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    boatEspHighlights[boatModel] = nil\n                end\n            end\n            \n            local function clearAllBoatEsp()\n                for model, data in pairs(boatEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                boatEspHighlights = {}\n            end\n            \n            local function scanAllBoats()\n                if not boatFolder then return end\n                for _, child in ipairs(boatFolder:GetDescendants()) do\n                    if typeof(child) == "Instance" and child:IsA("Model") and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                        if not boatEspHighlights[child] then\n                            pcall(function() createBoatEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startBoatEsp()\n                if boatEspEnabled then return end\n                boatEspEnabled = true\n                scanAllBoats()\n                \n                if boatFolder then\n                    local boatAddedConn = boatFolder.DescendantAdded:Connect(function(desc)\n                        if boatEspEnabled and typeof(desc) == "Instance" and desc:IsA("Model") and desc.Parent and typeof(desc.Parent) == "Instance" and desc.Parent:IsA("Folder") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not boatEspHighlights[desc] then\n                                    createBoatEsp(desc)\n                                end\n                            end)\n                        end\n                    end)\n                    table.insert(espConnections, { conn = boatAddedConn })\n                end\n                \n                boatEspThread = task.spawn(function()\n                    while boatEspEnabled do\n                        task.wait(10)\n                        if boatEspEnabled then\n                            pcall(function()\n                                for model, data in pairs(boatEspHighlights) do\n                                    if not model.Parent then\n                                        removeBoatEsp(model)\n                                    end\n                                end\n                                scanAllBoats()\n                            end)\n                        end\n                    end\n                end)\n                \n                NexusLib:Notify({ Title = "Boat ESP", Message = "Boat ESP enabled!", Duration = 2 })\n            end\n            \n            local function stopBoatEsp()\n                boatEspEnabled = false\n                if boatEspThread then\n                    task.cancel(boatEspThread)\n                    boatEspThread = nil\n                end\n                clearAllBoatEsp()\n                NexusLib:Notify({ Title = "Boat ESP", Message = "Boat ESP disabled!", Duration = 2 })\n            end\n            \n            Cfg.register(EspSection:CreateToggle(Cfg.wrap("Toggle", "Boat ESP", {\n                Name = "Boat ESP",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startBoatEsp()\n                    else\n                        stopBoatEsp()\n                    end\n                end\n            })), "Toggle", "Boat ESP", {\n                Name = "Boat ESP",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startBoatEsp()\n                    else\n                        stopBoatEsp()\n                    end\n                end\n            })\n        end\n        \n        -- ===== SECRET ROD ESP =====\n        do\n            local secretRodEspEnabled = false\n            local secretRodEspThread = nil\n            local secretRodEspHighlights = {}\n            local secretRodFolder = workspace:FindFirstChild("SecretRod")\n            \n            local function createSecretRodEsp(rodModel)\n                if not rodModel or typeo