'and" then\n            return getRecommendedIsland()\n        else\n            for _, island in ipairs(NexusState.islands) do\n                if island.name == selectedIslandName then\n                    return island\n                end\n            end\n            return nil\n        end\n    end\n\n    -- ===== parse / getCurrentQuestProgress helpers (unchanged) =====\n    local function parseQuestString(str)\n        if not str or str == "" then return nil, nil end\n        local parts = {}\n        for part in string.gmatch(str, "[^,]+") do table.insert(parts, part) end\n        if #parts >= 3 then\n            local target = nil\n            local typ = nil\n            if string.find(parts[1], "Boss") then\n                target = tonumber(parts[3])\n                typ = parts[1]\n            else\n                target = tonumber(parts[2])\n                typ = parts[3]\n            end\n            if target and typ then return target, typ end\n        end\n        return nil, nil\n    end\n\n    local function getCurrentQuestProgress()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return nil end\n        local quest = userData:FindFirstChild("Quest")\n        if not quest then return nil end\n        local main = quest:FindFirstChild("Main")\n        if not main then return nil end\n        for _, folder in pairs(main:GetChildren()) do\n            if typeof(folder) == "Instance" and typeof(folder) == "Instance" and folder:IsA("Folder") and (folder.Name == "Easy Ticket Quest" or folder.Name == "Hard Ticket Quest") then\n                local current = nil\n                local target = nil\n                local typ = nil\n                local questName = folder.Name\n                for _, child in pairs(folder:GetChildren()) do\n                    if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("NumberValue") or child:IsA("IntValue") then\n                        if child.Name == "1" then\n                            current = child.Value\n                        end\n                    end\n                end\n                local objective = folder:FindFirstChild("Objective")\n                if objective then\n                    for _, child in pairs(objective:GetChildren()) do\n                        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("StringValue") and child.Name == "1" then\n                            local val = child.Value\n                            if val and val ~= "" then\n                                NexusState.ticketObjectiveText = tostring(val)\n                                local t, ty = parseQuestString(val)\n                                if t and ty then\n                                    target = t\n                                    typ = ty\n                                end\n                            end\n                        end\n                    end\n                end\n                if current and target and typ then\n                    return current, target, questName, typ\n                end\n            end\n        end\n        return nil\n    end\n\n    local function updateQuestStatus()\n        local current, target, questName, typ = getCurrentQuestProgress()\n        if current and target and questName then\n            NexusState.ticketTargetCount = target\n            NexusState.ticketCurrentCount = current\n            NexusState.ticketQuestActive = true\n            if current >= target then\n                if not NexusState.ticketQuestClaimed then\n                    NexusLib:Notify({ Title = "Quest", Message = "Complete! Claiming reward...", Duration = 2 })\n                    -- TP to NPC, turn in with retries, chain next quest right away.\n                    local turnedIn = false\n                    for _ = 1, 5 do\n                        if ticketGoFire("Quest") then\n                            for _ = 1, 6 do\n                                task.wait(0.15)\n                                if not getCurrentQuestProgress() then\n                                    turnedIn = true\n                                    break\n                                end\n                            end\n                        end\n                        if turnedIn then break end\n                        task.wait(0.2)\n                    end\n                    if turnedIn then\n                        NexusState.ticketQuestClaimed = true\n                        NexusState.ticketLastFire = 0\n                        NexusState.ticketFailCount = 0\n                        NexusState.isDoingUseBaitQuest = false\n                        disableAllFishing()\n                        NexusState.ticketQuestActive = false\n                        NexusLib:Notify({ Title = "Quest", Message = "Turned in. Claim toggle takes next quest.", Duration = 3 })\n                    else\n                        NexusLib:Notify({ Title = "Quest", Message = "Turn-in failed, retrying...", Duration = 2 })\n                    end\n                end\n                NexusState.isDoingUseBaitQuest = false\n                Fishing.Flags.AutoSkill = false\n                Fishing.Flags.AutoSkillCheck = false\n                NexusState.ticketQuestActive = false\n                return\n            end\n            NexusState.ticketQuestClaimed = false\n            \n            -- Teleport to target island (manual choice wins)\n            local targetIsland = getTargetIsland()\n            if targetIsland then\n                local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")\n                if hrp then\n                    local targetPos = targetIsland.cframe.Position + Vector3.new(0, 5, 0)\n                    if (hrp.Position - targetPos).Magnitude > 25 and (tick() - (NexusState.ticketLastTele or 0) > 3) then\n                        NexusState.ticketLastTele = tick()\n                        safeTeleport(hrp, CFrame.new(targetPos))\n                    end\n                end\n            end\n            \n                        local need = string.lower(tostring(typ or "") .. " " .. tostring(NexusState.ticketObjectiveText or ""))\n            local function needHas(...)\n                for _, k in ipairs({...}) do\n                    if string.find(need, k, 1, true) then return true end\n                end\n                return false\n            end\n            NexusState.isDoingUseBaitQuest = false\n            -- Ticket pool: use bait / catch fish / heavy fish (1.5M) / use skill.\n            -- No boss quests here, so boss words inside fish names must not trigger boss farm.\n            if needHas("usebait", "use bait", "bait") then\n                NexusState.isDoingUseBaitQuest = true\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                Fishing.Flags.AnchorLock = true\n                Fishing.Flags.AutoSkill = true\n                Fishing.Flags.AutoSkillCheck = true\n                MiscFlags.AutoBuy = true\n                local buyable = GetBuyableBaits()\n                local found = false\n                for _, name in ipairs(buyable) do\n                    if name == "Basic Bait" then\n                        NexusState.selectedBait = name\n                        found = true\n                        break\n                    end\n                end\n                if not found then\n                    NexusState.selectedBait = buyable[1] or "No bait available"\n                end\n                MiscFlags.AutoEquipBait = true\n            elseif needHas("skill") then\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                Fishing.Flags.AutoSkill = true\n                Fishing.Flags.AutoSkillCheck = true\n                Fishing.Flags.AnchorLock = true\n            elseif needHas("weight", "kg", "heavy", "1.5m", "1,5m", "1500000") then\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                pcall(function() Events.UpdateFishProgression:FireServer() end)\n            elseif needHas("fish", "catch", "fishing") then\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n                pcall(function() Events.UpdateFishProgression:FireServer() end)\n            else\n                enableBasicFishing()\n                Fishing.Flags.AutoFarmBoss = false\n                Fishing.Flags.AutoFarmSecretBoss = false\n            end\n        else\n            if NexusState.ticketQuestActive then\n                NexusState.ticketQuestActive = false\n                NexusState.ticketTargetCount = 0\n                NexusState.ticketCurrentCount = 0\n                NexusState.isDoingUseBaitQuest = false\n                Fishing.Flags.AutoSkill = false\n                Fishing.Flags.AutoSkillCheck = false\n                disableAllFishing()\n            end\n            NexusState.isDoingUseBaitQuest = false\n            NexusState.ticketQuestClaimed = false\n            NexusState.ticketLastFire = 0\n            NexusState.ticketFailCount = 0\n            NexusState.ticketObjectiveText = nil\n        end\n    end\n\n    local function startAutoDoLoop()\n        if NexusState.autoDoThread then return end\n        NexusState.autoDoThread = task.spawn(function()\n            while NexusState.autoDoRunning do\n                pcall(updateQuestStatus)\n                task.wait(1)\n            end\n            NexusState.autoDoThread = nil\n        end)\n    end\n\n    local autoDoToggle = Cfg.register(DoSection:CreateToggle(Cfg.wrap("Toggle", "Auto Do Ticket Quest (Fast)", {\n        Name = "Auto Do Ticket Quest (Fast)",\n        Default = false,\n        Callback = function(value)\n            NexusState.autoDoRunning = value\n            if value then\n                if NexusState.autoDoThread then\n                    task.cancel(NexusState.autoDoThread)\n                    NexusState.autoDoThread = nil\n                end\n                startAutoDoLoop()\n                NexusLib:Notify({ Title = "Auto Do Quest", Message = "Started fast quest monitoring", Duration = 2 })\n            else\n                if NexusState.autoDoThread then\n                    task.cancel(NexusState.autoDoThread)\n                    NexusState.autoDoThread = nil\n                end\n                disableAllFishing()\n                NexusState.isDoingUseBaitQuest = false\n                NexusLib:Notify({ Title = "Auto Do Quest", Message = "Stopped", Duration = 2 })\n            end\n        end\n    })), "Toggle", "Auto Do Ticket Quest (Fast)", {\n        Name = "Auto Do Ticket Quest (Fast)",\n        Default = false,\n        Callback = function(value)\n            NexusState.autoDoRunning = value\n            if value then\n                if NexusState.autoDoThread then\n                    task.cancel(NexusState.autoDoThread)\n                    NexusState.autoDoThread = nil\n                end\n                startAutoDoLoop()\n                NexusLib:Notify({ Title = "Auto Do Quest", Message = "Started fast quest monitoring", Duration = 2 })\n            else\n                if NexusState.autoDoThread then\n                    task.cancel(NexusState.autoDoThread)\n                    NexusState.autoDoThread = nil\n                end\n                disableAllFishing()\n                NexusState.isDoingUseBaitQuest = false\n                NexusLib:Notify({ Title = "Auto Do Quest", Message = "Stopped", Duration = 2 })\n            end\n        end\n    })\n\n    -- ===== T    local direct = tonumber(s)\n    if direct then return direct end\n    local num, suffix = s:match("^([%d%.]+)%s*([KkMmBbTt])%+?$")\n    num = tonumber(num)\n    if not num then return nil end\n    local mult = { K = 1000, M = 1000000, B = 1000000000, T = 1000000000000 }\n    local m = mult[string.upper(suffix or "")]\n    if not m then return nil end\n    return num * m\nend\n\nlocal function parseCraftFishEntry(item)\n    if not item then return nil, nil, 0 end\n    local rawName = tostring(item.Name or "")\n    rawName = string.split(rawName, "| Favorite")[1]\n    local count = 1\n    pcall(function()\n        if type(item.Value) == "number" then count = item.Value end\n    end)\n    local parts = {}\n    for part in string.gmatch(rawName, "[^|]+") do table.insert(parts, part) end\n    local function trim(s) return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "") end\n    local fishName = trim(parts[1])\n    local weight = nil\n    if #parts >= 2 then\n        weight = parseCraftWeight(string.split(trim(parts[2]), " ")[1])\n    end\n    if not weight then\n        pcall(function()\n            local w = item:GetAttribute("Weight")\n            if type(w) == "number" and w > 0 then weight = w end\n        end)\n    end\n    if (not weight) and type(item.Value) == "string" and string.find(item.Value, "|", 1, true) then\n        local vparts = {}\n        for part in string.gmatch(item.Value, "[^|]+") do table.insert(vparts, part) end\n        if #vparts >= 2 then\n            weight = parseCraftWeight(string.split(trim(vparts[2]), " ")[1])\n        end\n        if fishName == "" and #vparts >= 1 then fishName = trim(vparts[1]) end\n    end\n    if fishName == "" then return nil, nil, 0 end\n    if type(count) ~= "number" or count < 1 then count = 1 end\n    return fishName, weight, math.floor(count)\nend\n\nlocal function GetBuyableBaits()\n    local _bbNow = tick()\n    if NexusState.cachedBuyableBaits and NexusState.cachedBuyableBaitsAt and (_bbNow - NexusState.cachedBuyableBaitsAt < 30) then\n        return NexusState.cachedBuyableBaits\n    end\n    local baits = {}\n    if not Info or not Info:FindFirstChild("Bait") then return {"No bait available"} end\n    for _, child in pairs(Info.Bait:GetChildren()) do\n        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("ModuleScript") then\n            local success, mod = pcall(require, child)\n            if success and type(mod) == "table" and mod.Price and mod.Price > 0 then\n                table.insert(baits, child.Name)\n            end\n        end\n    end\n    if #baits == 0 then return {"No bait available"} end\n    NexusState.cachedBuyableBaits = baits\n    NexusState.cachedBuyableBaitsAt = _bbNow\n    return baits\nend\n\nlocal function saveRoutineFlags()\n    NexusState.savedRoutineFlags = {\n        AutoCast = Fishing.Flags.AutoCast,\n        AnchorLock = Fishing.Flags.AnchorLock,\n        AutoSkill = Fishing.Flags.AutoSkill,\n        AutoSell = MiscFlags.AutoSell,\n        AutoSkillCheck = Fishing.Flags.AutoSkillCheck,\n        AntiAFK = Fishing.Flags.AntiAFK,\n        AutoFarmBoss = Fishing.Flags.AutoFarmBoss,\n        AutoFarmSecretBoss = Fishing.Flags.AutoFarmSecretBoss,\n        AutoBuy = MiscFlags.AutoBuy,\n        AutoEquipBait = MiscFlags.AutoEquipBait,\n        AutoEquipRod = MiscFlags.AutoEquipRod,\n    }\nend\n\nlocal function restoreRoutineFlags()\n    if NexusState.savedRoutineFlags then\n        Fishing.Flags.AutoCast = NexusState.savedRoutineFlags.AutoCast\n        Fishing.Flags.AnchorLock = NexusState.savedRoutineFlags.AnchorLock\n        Fishing.Flags.AutoSkill = NexusState.savedRoutineFlags.AutoSkill\n        MiscFlags.AutoSell = NexusState.savedRoutineFlags.AutoSell\n        Fishing.Flags.AutoSkillCheck = NexusState.savedRoutineFlags.AutoSkillCheck\n        Fishing.Flags.AntiAFK = NexusState.savedRoutineFlags.AntiAFK\n        Fishing.Flags.AutoFarmBoss = NexusState.savedRoutineFlags.AutoFarmBoss\n        Fishing.Flags.AutoFarmSecretBoss = NexusState.savedRoutineFlags.AutoFarmSecretBoss\n        MiscFlags.AutoBuy = NexusState.savedRoutineFlags.AutoBuy\n        MiscFlags.AutoEquipBait = NexusState.savedRoutineFlags.AutoEquipBait\n        MiscFlags.AutoEquipRod = NexusState.savedRoutineFlags.AutoEquipRod\n        NexusState.savedRoutineFlags = nil\n    else\n        Fishing.Flags.AutoFarmBoss = false\n        Fishing.Flags.AutoFarmSecretBoss = false\n    end\nend\n\n-- Ticket fishing mode: auto cast + anchor lock + auto skill + rod equip,\n-- so turning on Auto Do Ticket is enough to work all 8 ticket quests.\nlocal function enableBasicFishing()\n    if not NexusState.savedRoutineFlags then saveRoutineFlags() end\n    Fishing.Flags.AutoCast = true\n    Fishing.Flags.AnchorLock = true\n    Fishing.Flags.AutoSkill = true\n    Fishing.Flags.AutoSkillCheck = true\n    MiscFlags.AutoEquipRod = true\nend\n\nlocal function disableAllFishing()\n    restoreRoutineFlags()\nend\n\n-- Teleport without the sky-drop freeze: a character held at +1000 sky sits in\n-- freefall, so AssemblyLinearVelocity grows huge. Carrying that velocity into a\n-- ground teleport slams the Humanoid into the floor and sticks it (frozen).\n-- Zero it on both ends and wake the Humanoid so movement resumes instantly.\nlocal function safeTeleport(hrp, cf)\n    if not hrp or not cf then return end\n    local model = hrp.Parent\n    local humanoid = model and model:FindFirstChildOfClass("Humanoid")\n    -- Never freeze the live character: Anchored + task.wait() inside a\n    -- RenderStepped/Heartbeat-adjacent call stalls physics for a frame and\n    -- leaves the Humanoid seated/stuck, so walking looks frozen afterwards.\n    -- PivotTo moves the whole model atomically with no Anchored pin.\n    local ok = false\n    if model then\n        pcall(function()\n            model:PivotTo(cf)\n            ok = true\n        end)\n    end\n    if not ok then\n        pcall(function()\n            hrp.AssemblyLinearVelocity = Vector3.zero\n            hrp.AssemblyAngularVelocity = Vector3.zero\n            hrp.CFrame = cf\n        end)\n    end\n    pcall(function()\n        hrp.Anchored = false\n        hrp.AssemblyLinearVelocity = Vector3.zero\n        hrp.AssemblyAngularVelocity = Vector3.zero\n    end)\n    if humanoid then\n        pcall(function()\n            if humanoid.Seated then humanoid.Seated = false end\n            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)\n        end)\n    end\nend\n\n-- ===== EGO + TIGER CHECK (dieu kien cho Island 11) =====\n-- Island 11 chi duoc recommend khi user co ca rod Ego va Tiger trong kho.\nlocal function hasEgoAndTiger()\n    local p = GetPlayerData()\n    if not p then return false end\n    local rodFolder = p:FindFirstChild("FishingRodInventory") or p:FindFirstChild("Rod")\n    if not rodFolder then return false end\n    local hasEgo, hasTiger = false, false\n    for _, f in pairs(rodFolder:GetChildren()) do\n        local n = string.lower(tostring(f.Name))\n        if string.find(n, "ego") then hasEgo = true end\n        if string.find(n, "tiger") then hasTiger = true end\n    end\n    return hasEgo and hasTiger\nend\n\nlocal function getTotalPower()\n    local _pwNow = tick()\n    if NexusState.cachedPower and NexusState.cachedPowerAt and (_pwNow - NexusState.cachedPowerAt < 5) then\n        return NexusState.cachedPower\n    end\n    local total = 0\n    local char = LocalPlayer.Character\n    if char then\n        local stats = char:FindFirstChild("Stats")\n        if stats then\n            local rp = stats:FindFirstChild("RodPower")\n            if typeof(rp) == "Instance" and rp:IsA("NumberValue") then total = total + rp.Value end\n            local fp = stats:FindFirstChild("FishPower")\n            if typeof(fp) == "Instance" and fp:IsA("NumberValue") then total = total + fp.Value end\n        end\n        local attr = char:GetAttribute("RodPower")\n        if attr and type(attr) == "number" and attr > 0 and total == 0 then total = attr end\n    end\n    if total == 0 then\n        local userId = LocalPlayer.UserId\n        local userData = Data:FindFirstChild(tostring(userId))\n        if userData then\n            local rodNameValue = userData:FindFirstChild("FishingRod")\n            if rodNameValue then\n                local rodName = rodNameValue.Value\n                if rodName and rodName ~= "" then\n                    local rodModule = Info:FindFirstChild("Inventory") and Info.Inventory:FindFirstChild(rodName)\n                    if rodModule then\n                        local success, rodData = pcall(require, rodModule)\n                        if success and type(rodData) == "table" then\n                            total = rodData.Power or 0\n                        end\n                    end\n                end\n            end\n        end\n    end\n    NexusState.cachedPower = total\n    NexusState.cachedPowerAt = _pwNow\n    return total\nend\n\nlocal function getRecommendedIsland()\n    local _rcNow = tick()\n    if NexusState.cachedRecommended and NexusState.cachedRecommendedAt and (_rcNow - NexusState.cachedRecommendedAt < 5) then\n        return NexusState.cachedRecommended\n    end\n    local currentPower = getTotalPower()\n    local eligible = {}\n    for _, island in ipairs(NexusState.islands) do\n        -- Island 11 (if u have ego and tiger): chi chon khi co ca rod Ego va Tiger\n        if island.name ~= "Island 11" or hasEgoAndTiger() then\n            if (island.power or 0) <= currentPower then\n                table.insert(eligible, island)\n            end\n        end\n    end\n    table.sort(eligible, function(a, b) return a.power > b.power end)\n    NexusState.cachedRecommended = eligible[2] or eligible[1]\n    NexusState.cachedRecommendedAt = _rcNow\n    return NexusState.cachedRecommended\nend\n\nlocal function isHoldingFishingRod()\n    local char = LocalPlayer.Character\n    if not char then return false end\n    local typ = char:GetAttribute("Type")\n    if typ and string.lower(tostring(typ)) == "fishing rod" then return true end\n    return false\nend\n\n-- ============================================================\n\n-- ============================================================\n-- ===== CONFIG SYSTEM (save / load / auto-load / import-export) =====\n-- ============================================================\n-- Every Toggle / Dropdown / MultiDropdown / Textbox with a static English Name is\n-- registered here through Cfg.wrap(kind, name, config) at creation time. The config\n-- table itself is untouched (defaults still come from Default = ...), the registry\n-- only keeps the live handle so save/load can Get/Set values later.\n--\n-- Save format is a flat { [controlName] = value } table, JSON-encoded. Control\n-- names are unique across the whole hub (verified), so no tab/section prefix is\n-- needed and configs stay compatible even if a control moves sections.\ndo\n    local ConfigSys = {}\n    ConfigSys.registry = {}   -- [name] = { kind = "toggle"|"dropdown"|"multi"|"text", get = fn, set = fn }\n    ConfigSys.ordered = {}    -- registration order, for stable exports\n    ConfigSys.FILE = "NexusHub_Config.json"\n    ConfigSys.AUTO_FILE = "NexusHub_AutoLoad.json"\n    ConfigSys._saving = false\n\n    local function cfgKind(callKind)\n        if callKind == "Toggle" then return "toggle" end\n        if callKind == "Dropdown" then return "dropdown" end\n        if callKind == "MultiDropdown" then return "multi" end\n        return "text"\n    end\n\n    -- Wrap a control config table: pass through untouched, remember the name so\n    -- the returned handle can be registered right after creation.\n    function ConfigSys.wrap(callKind, name, config)\n        config = config or {}\n        config._CfgKind = callKind\n        config._CfgName = name\n        return config\n    end\n\n    function ConfigSys.register(handle, callKind, name, config)\n        if not handle or not name the',
