4650220,65989,155,11678,617,1938.,52370,4077.,"%\xD5\xD1M\xA6\xD7\xF2\x8B\x8F%jpT\xC5\xB5w\x9D\x19\x86\xA1\xF7\x14A\x17RmBKoFYDjhAoXAiPb!)eYPsYN1m","f2F}vt","0_C^,,V%",59539,3173845856,'") then\n                                local hrp = nanjiang:FindFirstChild("HumanoidRootPart")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            NexusState.Reroll.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.Reroll.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.Reroll.teleported then\n                        NexusLib:Notify({ Title = "Reroll", Message = "Could not find Nanjiang, teleport failed. Continuing anyway.", Duration = 3 })\n                    end\n                end\n\n                NexusState.Reroll.running = true\n                NexusLib:Notify({ Title = "Reroll", Message = "Reroll started... Target: " .. targetTrait, Duration = 2 })\n\n                NexusState.Reroll.thread = task.spawn(function()\n                    local successCount = 0\n                    while NexusState.Reroll.running do\n                        local p2 = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                        local count = p2 and p2:FindFirstChild("Trait Reroll")\n                        if count and count.Value <= 0 then\n                            NexusLib:Notify({ Title = "Reroll", Message = "No rerolls left, stopping", Duration = 2 })\n                            break\n                        end\n                        local success, result = pcall(function()\n                            return RerollTrait:InvokeServer(skillName, ignoreLocked)\n                        end)\n                        if not success or not result then\n                            NexusLib:Notify({ Title = "Reroll", Message = "Reroll failed, stopping", Duration = 2 })\n                            break\n                        end\n                        successCount = successCount + 1\n                        local traitName = result.Name\n                        if traitName == targetTrait then\n                            NexusLib:Notify({ Title = "Reroll", Message = "Got " .. targetTrait .. " on " .. skillName .. " after " .. successCount .. " rerolls!", Duration = 3 })\n                            break\n                        end\n                        task.wait(0.15)\n                    end\n\n                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then\n                        local char = LocalPlayer.Character\n                        if char then\n                            local root = char:FindFirstChild("HumanoidRootPart")\n                            if root then\n                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)\n                                NexusState.Reroll.oldPosition = nil\n                                NexusState.Reroll.teleported = false\n                            end\n                        end\n                    end\n                    NexusState.Reroll.running = false\n                    NexusState.Reroll.thread = nil\n                    NexusLib:Notify({ Title = "Reroll", Message = "Stopped", Duration = 2 })\n                end)\n            end\n        })\n    end\n\n    -- Craft Bait\n    do\n        local CraftSection = ShopTab:CreateSection("Craft Bait")\n        Cfg.register(CraftSection:CreateTextbox(Cfg.wrap("Textbox", "Number of baits to craft", {\n            Name = "Number of baits to craft",\n            Placeholder = "1",\n            Default = "1",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })), "Textbox", "Number of baits to craft", {\n            Name = "Number of baits to craft",\n            Placeholder = "1",\n            Default = "1",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap("Dropdown", "Choose a Bait", {\n            Name = "Choose a Bait",\n            Options = {"Rainbow Bait", "Frost Bait", "Nameless Bait"},\n            Default = "Rainbow Bait",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })), "Dropdown", "Choose a Bait", {\n            Name = "Choose a Bait",\n            Options = {"Rainbow Bait", "Frost Bait", "Nameless Bait"},\n            Default = "Rainbow Bait",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap("Dropdown", "Craft Method", {\n            Name = "Craft Method",\n            Options = {"Instant", "Teleport"},\n            Default = "Instant",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })), "Dropdown", "Craft Method", {\n            Name = "Craft Method",\n            Options = {"Instant", "Teleport"},\n            Default = "Instant",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })\n\n        local BAIT_RECIPES = {\n            ["Rainbow Bait"] = {\n                {name = "Colossal Tigerfish", minKg = 3000000, maxKg = 6000000},\n                {name = "Heavenpiercer Turtle", minKg = 3000000, maxKg = 6000000},\n                {name = "Golden Guardian Fish", minKg = 1000000, maxKg = 3000000},\n                {name = "Crimson Electric Eel", minKg = 3000000, maxKg = 4000000},\n            },\n            ["Frost Bait"] = {\n                {name = "Frost Kingfish", minKg = 4000000, maxKg = 7000000},\n                {name = "Ascended Perch", minKg = 900000, maxKg = 1000000},\n                {name = "Primordial Kunfish Overlord", minKg = 1000000, maxKg = 1600000},\n                {name = "Warbringer Shark", minKg = 500000, maxKg = 800000},\n            },\n            ["Nameless Bait"] = {\n                {name = "Mountain Fish", minKg = 1000000, maxKg = 5000000},\n                {name = "Tiger Mirefish", minKg = 1000000, maxKg = 3000000},\n                {name = "Mirage Lanternfish", minKg = 3000000, maxKg = 5000000},\n                {name = "Octoparasitic Fish", minKg = 3000000, maxKg = 5000000},\n            }\n        }\n\n        local function checkMaterials(baitName, quantity)\n            local recipe = BAIT_RECIPES[baitName]\n            if not recipe then return false, "No recipe found for " .. baitName end\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false, "Player data not found" end\n            local inventory = userData:FindFirstChild("Inventory")\n            if not inventory then return false, "Inventory not found" end\n            local fishCount = {}\n            for _, req in ipairs(recipe) do fishCount[req.name] = 0 end\n            for _, item in pairs(inventory:GetChildren()) do\n                local fishName, weight, count = parseCraftFishEntry(item)\n                if fishName and fishName ~= "" then\n                    local req = nil\n                    for _, r in ipairs(recipe) do\n                        if r.name == fishName then req = r; break end\n                    end\n                    if req then\n                        if weight and weight >= req.minKg and weight <= req.maxKg then\n                            fishCount[req.name] = fishCount[req.name] + count\n                        end\n                    end\n                end\n            end\n            local missing = {}\n            for _, req in ipairs(recipe) do\n                local count = fishCount[req.name] or 0\n                if count < quantity then\n                    table.insert(missing, req.name .. " (can " .. quantity .. ", co " .. count .. ")")\n                end\n            end\n            if #missing > 0 then\n                return false, "Missing materials: " .. table.concat(missing, ", ")\n            end\n            return true, "Materials are sufficient!"\n        end\n\n        local function craftBait()\n            local qty = NexusState.craftBaitQuantity\n            local ok, msg = checkMaterials(NexusState.craftBaitName, qty)\n            if not ok then\n                NexusLib:Notify({ Title = "Craft Bait", Message = msg, Duration = 4 })\n                return\n            end\n            local method = NexusState.craftBaitMethod or "Instant"\n            local teleported = false\n            if method == "Teleport" then\n                local npc = Workspace:FindFirstChild("NPC")\n                if npc then\n                    local buyBait = npc:FindFirstChild("BuyBait")\n                    if buyBait then\n                        local children = buyBait:GetChildren()\n                        if #children >= 5 then\n                            local targetModel = children[5]\n                            if typeof(targetModel) == "Instance" and targetModel:IsA("Model") then\n                                local hrp = targetModel:FindFirstChild("HumanoidRootPart")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            NexusState.lastCraftBaitPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n            local success, err = pcall(function()\n                Events.CraftBait:FireServer(NexusState.craftBaitName, qty)\n            end)\n            if success then\n                NexusLib:Notify({ Title = "Craft Bait", Message = "Crafted " .. qty .. "x " .. NexusState.craftBaitName, Duration = 2 })\n            else\n                NexusLib:Notify({ Title = "Craft Bait", Message = "Failed: " .. tostring(err), Duration = 2 })\n            end\n            if teleported and NexusState.lastCraftBaitPosition then\n                task.wait(0.3)\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild("HumanoidRootPart")\n                    if root then\n                        root.CFrame = CFrame.new(NexusState.lastCraftBaitPosition)\n                        NexusState.lastCraftBaitPosition = nil\n                    end\n                end\n            end\n        end\n\n        local autoCraftToggle = Cfg.register(CraftSection:CreateToggle(Cfg.wrap("Toggle", "Auto craft bait", {\n            Name = "A  local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            applyLanguageToGui(pg:FindFirstChild("NexusPanel"))\n            applyLanguageToGui(pg:FindFirstChild("NexusNotifications"))\n        end\n        pcall(function()\n            local cg = game:GetService("CoreGui")\n            if cg then\n                applyLanguageToGui(cg:FindFirstChild("NexusPanel"))\n                applyLanguageToGui(cg:FindFirstChild("NexusNotifications"))\n            end\n        end)\n    end\n\n    function I18n.initListeners()\n        local function hookGui(gui)\n            if not gui then return end\n            gui.DescendantAdded:Connect(function(desc)\n                task.wait(0.03)\n                translateObject(desc)\n            end)\n        end\n\n        local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            local panel = pg:FindFirstChild("NexusPanel")\n            if panel then hookGui(panel) end\n            local notifs = pg:FindFirstChild("NexusNotifications")\n            if notifs then hookGui(notifs) end\n\n            pg.ChildAdded:Connect(function(child)\n                if child.Name == "NexusPanel" or child.Name == "NexusNotifications" then\n                    hookGui(child)\n                    task.wait(0.1)\n                    applyLanguageToGui(child)\n                end\n            end)\n        end\n\n        pcall(function()\n            local cg = game:GetService("CoreGui")\n            if cg then\n                local panel = cg:FindFirstChild("NexusPanel")\n                if panel then hookGui(panel) end\n                local notifs = cg:FindFirstChild("NexusNotifications")\n                if notifs then hookGui(notifs) end\n\n                cg.ChildAdded:Connect(function(child)\n                    if child.Name == "NexusPanel" or child.Name == "NexusNotifications" then\n                        hookGui(child)\n                        task.wait(0.1)\n                        applyLanguageToGui(child)\n                    end\n                end)\n            end\n        end)\n    end\nend\n\n-- ===== FAKE NAME (STREAMER MODE) CORE =====\n-- ============================================================\ndo\n    local realName = LocalPlayer.Name\n    local realDisplayName = LocalPlayer.DisplayName\n    local fakeNameConn = nil\n    local fakeNameThread = nil\n    local maskIdsInText -- forward declare (dinh nghia ben duoi)\n\n    local function replacePlain(text, find, repl)\n        if find == "" then return text end\n        local parts = {}\n        local start = 1\n        while true do\n            local s, e = string.find(text, find, start, true)\n            if not s then\n                table.insert(parts, string.sub(text, start))\n                break\n            end\n            table.insert(parts, string.sub(text, start, s - 1))\n            table.insert(parts, repl)\n            start = e + 1\n        end\n        return table.concat(parts)\n    end\n\n    local function replaceTextInObject(obj)\n        if not NexusState.fakeNameEnabled then return end\n        if not obj or typeof(obj) ~= "Instance" then return end\n        pcall(function()\n            if typeof(obj) == "Instance" and typeof(obj) == "Instance" and obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then\n                local text = obj.Text\n                if text and #text > 0 then\n                    local updated = false\n                    if realDisplayName ~= "" and string.find(text, realDisplayName, 1, true) then\n                        text = replacePlain(text, realDisplayName, NexusState.fakeDisplayName or "NexusPlayer")\n                        updated = true\n                    end\n                    if realName ~= "" and string.find(text, realName, 1, true) then\n                        text = replacePlain(text, realName, NexusState.fakeName or "NexusPlayer")\n                        updated = true\n                    end\n                    -- Guild display: doi ten guild that -> fake guild de khong bi ban\n                    if NexusState.realGuildName and #NexusState.realGuildName > 0 then\n                        local rg = tostring(NexusState.realGuildName)\n                        if rg ~= "ZION" and not string.find(text, "ZION", 1, true) and string.find(text, rg, 1, true) then\n                            text = replacePlain(text, rg, NexusState.fakeGuildName or "NexusGuild")\n                            updated = true\n                        end\n                    end\n                    -- Che luon ID (UserId / PlaceId / JobId) chu khong chi ten\n                    if maskIdsInText then\n                        local masked, idChanged = maskIdsInText(text)\n                        if idChanged then\n                            text = masked\n                            updated = true\n                        end\n                    end\n                    if updated then\n                        obj.Text = text\n                    end\n                end\n            end\n        end)\n    end\n\n    -- Che ID: doi ten khong thoi van bi report vi nguoi ta doc UserId / PlaceId /\n    -- JobId tren man hinh (hoac trong anh chup). Nen phai che luon cac ID nay.\n    local realUserId = tostring(LocalPlayer.UserId)\n    local realPlaceId = tostring(game.PlaceId)\n\n    function maskIdsInText(text)\n        if not NexusState.fakeNameEnabled then return text, false end\n        local changed = false\n        if #realUserId >= 5 and string.find(text, realUserId, 1, true) then\n            if (NexusState.fakeIdMode or 1) == 2 then\n                text = string.gsub(text, realUserId, "****")\n            else\n                text = string.gsub(text, realUserId, tostring(NexusState.fakeUserId or "0"))\n            end\n            changed = true\n        end\n        if #realPlaceId >= 5 and string.find(text, realPlaceId, 1, true) then\n            text = string.gsub(text, realPlaceId, "0000000000")\n            changed = true\n        end\n        local guidPat = "%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x"\n        if string.find(text, guidPat) then\n            text = string.gsub(text, guidPat, "********-****-****-****-************")\n            changed = true\n        end\n        return text, changed\n    end\n\n    local function applyFakeNameToAll()\n        if not NexusState.fakeNameEnabled then return end\n        local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            for _, v in ipairs(pg:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        local char = LocalPlayer.Character\n        if char then\n            for _, v in ipairs(char:GetDescendants()) do\n                replaceTextInObject(v)\n            end\n        end\n        pcall(function()\n            local cg = game:GetService("CoreGui")\n            if cg then\n                for _, v in ipairs(cg:GetDescendants()) do\n                    replaceTextInObject(v)\n                end\n            end\n        end)\n    end\n\n    function NexusState.enableFakeName()\n        if NexusState.fakeNameEnabled then return end\n        NexusState.fakeNameEnabled = true\n        applyFakeNameToAll()\n\n        local pg = LocalPlayer:FindFirstChild("PlayerGui")\n        if pg then\n            fakeNameConn = pg.DescendantAdded:Connect(function(desc)\n                if NexusState.fakeNameEnabled then\n                    task.wait(0.05)\n                    replaceTextInObject(desc)\n                end\n            end)\n        end\n\n        fakeNameThread = task.spawn(function()\n            while NexusState.fakeNameEnabled do\n                pcall(applyFakeNameToAll)\n                task.wait(1.5)\n            end\n        end)\n        NexusLib:Notify({ Title = "Streamer Mode", Message = "Fake name active: " .. tostring(NexusState.fakeName), Duration = 2 })\n    end\n\n    function NexusState.disableFakeName()\n        NexusState.fakeNameEnabled = false\n        if fakeNameConn then fakeNameConn:Disconnect(); fakeNameConn = nil end\n        if fakeNameThread then task.cancel(fakeNameThread); fakeNameThread = nil end\n        NexusLib:Notify({ Title = "Streamer Mode", Message = "Fake name disabled", Duration = 2 })\n    end\nend\n\n-- ============================================================\n-- Chong "cau tren troi": khi dang bay / vua teleport, player lo lung tren khong\n-- nen phao khong roi trung nuoc -> cast phi hoai. Raycast xuong kiem tra nuoc.\nfunction NexusState.isOverWater()\n    local ok, result = pcall(function()\n        local char = LocalPlayer.Character\n        local root = char and char:FindFirstChild("HumanoidRootPart")\n        if not root then return false end\n\n        local params = RaycastParams.new()\n        params.FilterType = Enum.RaycastFilterType.Exclude\n        params.FilterDescendantsInstances = { char }\n        params.IgnoreWater = false\n\n        local hit = Workspace:Raycast(root.Position, Vector3.new(0, -200, 0), params)\n        if not hit then return false end\n\n        if hit.Instance == Workspace.Terrain and hit.Material == Enum.Material.Water then\n            return true\n        end\n        local n = string.lower(hit.Instance.Name)\n        if string.find(n, "water") or string.find(n, "ocean") or string.find(n, "sea") then\n            return true\n        end\n        return false\n    end)\n    if not ok then return true end -- loi thi cho cast, khong chan oan\n    return result\nend\n\nfunction NexusState.canCastNow()\n    if NexusState.flying then return false end\n    -- Khi bat auto cast / farm boss / farm secret: tele len troi la chu y\n    -- (chong detect), vay isOverWater se false -> bo qua kiem tra nuoc,\n    -- chi chan khi dang fly thu cong.\n    local F = NexusState.Fishing and NexusState.Fishing.Flags\n    if F and (F.AutoCast or F.AutoFarmBoss or F.AutoFarmSecretBoss) then\n        return true\n    end\n    return NexusState.isOverWater()\nend\n\n-- ===== UNIVERSAL BAIT MERCHANT LOCATOR =====\n-- ============================================================\nlocal function findBaitMerchantHRP()\n    local char = LocalPlayer.Character\n    local root = char and char:FindFirstChild("HumanoidRootPart")\n    local myPos = root and root.Position or Vector3.new(0, 0, 0)\n    local bestHRP = nil\n    local bestDist = math.huge\n\n    pcall(function()\n        local npcFolder = Workspace:FindFirstChild("NPC")\n        if npcFolder then\n            local bb = npcFolder:FindFirstChild("BuyBait")\n            if bb then\n                for _, model in ipairs(bb:GetChildren()) do\n                    if typeof(model) == "Instance" and typeof(model) == "Instance" and model:IsA("Model") then\n                        local hrp = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso") or model.PrimaryPart\n                        if hrp then\n                            local dist = (hrp.Position - myPos).Magnitude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n            local func = npcFolder:FindFirstChild("Function")\n            if func then\n                for _, model in ipairs(func:GetChildren()) do\n                    if typeof(model) == "Instance" and typeof(model) == "Instance" and model:IsA("Model") and (string.find(model.Name:lower(), "bait") or string.find(model.Name:lower(), "shop") or string.find(model.Name:lower(), "merchant")) then\n                        local hrp = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso") or model.PrimaryPart\n                        if hrp then\n                            local dist = (hrp.Position - myPos).Magni',
