"Auto Rebirth\"] = \"\",\n            [\"Auto craft bait\"] = \"\",\n            [\"Auto craft selected rod\"] = \"\",\n            [\"Auto fish for bait materials\"] = \"\",\n            [\"Fly Mode\"] = \" (Fly)\",\n            [\"Walk On Water\"] = \"\",\n            [\"Infinite Jump\"] = \"\",\n            [\"Noclip\"] = \"\",\n            [\"Full Bright\"] = \"\",\n            [\"Fake Name Display\"] = \"\",\n            [\"Anti-Report Nexus Users\"] = \" Nexus\",\n            [\"Enable Staff Watch\"] = \" Staff\",\n            [\"Enable Notifications\"] = \"\",\n            [\"UI Language\"] = \" UI\",\n            [\"Skill Mode\"] = \"\",\n            [\"Skill Sequence Order\"] = \"\",\n            [\"Skill Delay (seconds)\"] = \" ()\",\n            [\"Select Island\"] = \"\",\n            [\"Buy Now\"] = \"\",\n            [\"Craft rod now\"] = \"\",\n            [\"Craft bait now\"] = \"\",\n            [\"Exchange now\"] = \"\",\n            [\"Language\"] = \"\",\n            [\"Language set to: \"] = \": \"\n        },\n        id = {\n            [\"Session\"] = \"Sesi\",\n            [\"Routine\"] = \"Memancing\",\n            [\"Shop\"] = \"Toko\",\n            [\"Exchange\"] = \"Tukar\",\n            [\"Quests\"] = \"Misi\",\n            [\"Upgrade\"] = \"Peningkatan\",\n            [\"Teleport\"] = \"Teleportasi\",\n            [\"Settings\"] = \"Pengaturan\",\n            [\"Session overview\"] = \"Ringkasan Sesi\",\n            [\"Release notes\"] = \"Catatan Pembaruan\",\n            [\"Fishing routine\"] = \"Rutinitas Memancing\",\n            [\"Farm On Weather Section\"] = \"Auto Farm Cuaca Rahasia\",\n            [\"Skill profile\"] = \"Profil Skill\",\n            [\"Auto Equip\"] = \"Auto Pasang\",\n            [\"Auto Nameless Octoparasite\"] = \"Auto Gurita Tanpa Nama\",\n            [\"Auto Favorite Fish\"] = \"Auto Favoritkan Ikan\",\n            [\"Auto Pray Spirit\"] = \"Auto Doa ke Roh\",\n            [\"Auto Farm\"] = \"Auto Farm\",\n            [\"Index\"] = \"Indeks Ikan\",\n            [\"Upgrade Skill\"] = \"Tingkatkan Skill\",\n            [\"Craft Rod\"] = \"Buat Pancingan\",\n            [\"Auto Buy Bait\"] = \"Auto Beli Umpan\",\n            [\"Auto Buy Rod\"] = \"Auto Beli Pancingan\",\n            [\"Learn Skills\"] = \"Pelajari Skill\",\n            [\"Trait Reroll\"] = \"Reroll Sifat\",\n            [\"Craft Bait\"] = \"Buat Umpan\",\n            [\"Auto Gacha\"] = \"Auto Gacha\",\n            [\"Exchange Items\"] = \"Tukar Barang\",\n            [\"Auto Claim Ticket Quest\"] = \"Auto Klaim Misi Tiket\",\n            [\"Daily Quests\"] = \"Misi Harian\",\n            [\"Material Farming\"] = \"Farm Bahan\",\n            [\"Auto Do Ticket Quest\"] = \"Auto Jalankan Misi Tiket\",\n            [\"Character Upgrade\"] = \"Tingkatkan Karakter\",\n            [\"Character\"] = \"Karakter\",\n            [\"World & Misc\"] = \"Dunia & Lainnya\",\n            [\"Streamer Mode (Fake Name)\"] = \"Mode Streamer (Nama Palsu)\",\n            [\"Language & Localization\"] = \"Bahasa & Lok               if c and not c:GetAttribute(\"Fishing\") and NexusState.canCastNow() then\n                                Events.Fishing:FireServer()\n                            end\n                        end)\n                        task.wait(0.6)\n                    end\n                end)\n            end\n        })\n    end\n\n    local weatherIslands = {\n        [\"foggy\"] = \"Island 7\", [\"blazing sun\"] = \"Island 8\", [\"snowy\"] = \"Island 6\",\n        [\"windy\"] = \"Island 5\", [\"rainy\"] = \"Island 3\", [\"thunderstorm\"] = \"Island 2\"\n    }\n\n    local function getCurrentWeather()\n        local info = MainGui:FindFirstChild(\"Info\")\n        if info then\n            local infoFrame = info:FindFirstChild(\"Info\")\n            if infoFrame then\n                local weatherFrame = infoFrame:FindFirstChild(\"Weather\")\n                if weatherFrame then\n                    local val = weatherFrame:FindFirstChild(\"Value\")\n                    if val and typeof(val) == \"Instance\" then\n                        local text = ((typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") and val.Text or val.Value))\n                        return text:gsub(\"Weather:%s*\", \"\")\n                    end\n                end\n            end\n        end\n        return \"Clear\"\n    end\n\n    TPSection:CreateButton({\n        Name = \"Teleport To Current Weather\",\n        Callback = function()\n            local currentWeather = getCurrentWeather()\n            if currentWeather:lower() == \"clear\" or currentWeather == \"\" then\n                NexusLib:Notify({ Title = \"Weather TP\", Message = \"Server weather is Clear, no event to TP!\", Duration = 3 })\n                return\n            end\n            local targetIslandName = weatherIslands[currentWeather:lower()]\n            if targetIslandName then\n                for _, v in ipairs(NexusState.islands) do\n                    if v.name:lower() == targetIslandName:lower() then\n                        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                        if hrp then\n                            hrp.CFrame = CFrame.new(v.cframe.Position) + Vector3.new(0, 5, 0)\n                            NexusLib:Notify({ Title = \"Weather TP\", Message = \"Teleported to \" .. targetIslandName .. \" for \" .. currentWeather, Duration = 4 })\n                        end\n                        return\n                    end\n                end\n            else\n                NexusLib:Notify({ Title = \"Weather TP\", Message = \"Unknown weather island mapping for: \" .. currentWeather, Duration = 4 })\n            end\n        end\n    })\n\n    -- Server\n    do\n        local ServerSection = TeleportTab:CreateSection(\"Server\", \"Left\")\n        local b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'\n        local function b64decode(data)\n            data = string.gsub(data, '[^'..b64chars..'=]', '')\n            return (data:gsub('.', function(x)\n                if (x == '=') then return '' end\n                local r,f='',(b64chars:find(x, 1, true)-1)\n                for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end\n                return r;\n            end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)\n                if (#x ~= 8) then return '' end\n                local c=0\n                for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end\n                return string.char(c)\n            end))\n        end\n\n        local savedJobId = \"\"\n        local lastHopAt = 0\n        ServerSection:CreateTextbox({\n            Name = \"Join by Job ID\",\n            Placeholder = \"Paste Job ID here...\",\n            Default = \"\",\n            Callback = function(text)\n                if text and text ~= \"\" then\n                    local finalJobId = text\n                    local matchB64 = string.match(text, \"NEXUSHUB|([^%s]+)\")\n                    if matchB64 then\n                        local success, decoded = pcall(b64decode, matchB64)\n                        if success and decoded and decoded ~= \"\" then\n                            finalJobId = decoded\n                        end\n                    end\n                    if finalJobId == game.JobId then\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = \"Already in this server.\", Duration = 3 })\n                        return\n                    end\n                    if tick() - lastHopAt < 30 then\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = \"Hop cooldown, try again shortly.\", Duration = 3 })\n                        return\n                    end\n                    lastHopAt = tick()\n                    savedJobId = finalJobId\n                    NexusLib:Notify({ Title = \"Server Hop\", Message = \"Joining server...\", Duration = 3 })\n                    Services.TeleportService:TeleportToPlaceInstance(game.PlaceId, finalJobId, LocalPlayer)\n                end\n            end\n        })\n        ServerSection:CreateButton({\n            Name = \"Delete Job ID\",\n            Callback = function()\n                savedJobId = \"\"\n                NexusLib:Notify({ Title = \"Server Hop\", Message = \"Job ID cleared!\", Duration = 2 })\n            end\n        })\n    end\n\n    -- Islands\n    do\n        local IslandSection = TeleportTab:CreateSection(\"Islands\", \"Right\")\n        for _, v in ipairs(NexusState.islands) do\n            IslandSection:CreateButton({\n                Name = v.name,\n                Callback = function()\n                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        hrp.CFrame = CFrame.new(v.cframe.Position) + Vector3.new(0, 5, 0)\n                        NexusLib:Notify({ Title = \"Teleport\", Message = \"Teleported to \" .. v.name, Duration = 3 })\n                    end\n                end\n            })\n        end\n    end\n    -- ===== PLAYERS SECTION =====\n    do\n        local PlayerSection = TeleportTab:CreateSection(\"Players\", \"Right\")\n        \n        local selectedPlayer = nil\n        local playerDropdown = nil  -- Keep a reference to the dropdown\n        local playerList = {}\n        \n        -- List refresh helper\n        local function refreshPlayerList()\n            -- Read the player list\n            playerList = {}\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    table.insert(playerList, player.Name)\n                end\n            end\n            if #playerList == 0 then\n                table.insert(playerList, \"No other players\")\n                selectedPlayer = \"No other players\"\n            else\n                selectedPlayer = playerList[1]\n            end\n            \n            -- Remove the old dropdown if present\n            if playerDropdown and playerDropdown._frame then\n                pcall(function()\n                    playerDropdown._frame:Destroy()\n                end)\n                playerDropdown = nil\n            end\n            \n            -- Create the new dropdown\n            playerDropdown = PlayerSection:CreateDropdown({\n                Name = \"Select Player\",\n                Options = playerList,\n                Default = selectedPlayer,\n                Callback = function(value)\n                    selectedPlayer = value\n                end\n            })\n        end\n        \n        -- Create the dropdown for the first time\n        refreshPlayerList()\n        \n        -- Refresh List button\n        PlayerSection:CreateButton({\n            Name = \"Refresh List\",\n            Callback = function()\n                refreshPlayerList()\n                NexusLib:Notify({\n                    Title = \"Players\",\n                    Message = \"Player list refreshed! Found \" .. #playerList .. \" players.\",\n                    Duration = 2\n                })\n            end\n        })\n        \n        -- Teleport to Player button\n        PlayerSection:CreateButton({\n            Name = \"Teleport to Player\",\n            Callback = function()\n                if not selectedPlayer or selectedPlayer == \"No other players\" then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = \"No valid player selected!\", Duration = 2 })\n                    return\n                end\n                \n                local targetPlayer = nil\n                for _, player in ipairs(Players:GetPlayers()) do\n                    if player.Name == selectedPlayer then\n                        targetPlayer = player\n                        break\n                    end\n                end\n                \n                if not targetPlayer then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = \"Player not found! Try refreshing.\", Duration = 2 })\n                    return\n                end\n                \n                local character = targetPlayer.Character\n                if not character then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = targetPlayer.Name .. \" has no character!\", Duration = 2 })\n                    return\n                end\n                \n                local hrp = character:FindFirstChild(\"HumanoidRootPart\")\n                if not hrp then\n                    NexusLib:Notify({ Title = \"Teleport\", Message = \"Cannot find HumanoidRootPart!\", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild(\"HumanoidRootPart\")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({\n                    Title = \"Teleport\",\n                    Message = \"Teleported to \" .. targetPlayer.Name,\n                    Duration = 2\n                })\n            end\n        })\n    -- ===== SPECTATE PLAYER =====\n        local spectateEnabled = false\n        local spectateTarget = nil\n        local oldSubject = nil\n        local oldCameraType = nil\n        local espConnections = {}\n        \n        -- Start spectate\n        local function startSpectate()\n            if spectateEnabled then return end\n            \n            -- Find the first player other than yourself\n            local targetPlayer = nil\n            for _, player in ipairs(Players:GetPlayers()) do\n                if player ~= LocalPlayer then\n                    targetPlayer = player\n                    break\n                end\n            end\n            \n            if not targetPlayer then\n                NexusLib:Notify({ Title = \"Spectate\", Message = \"No other players to spectate!\", Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n                return\n            end\n            \n            -- Check whether the target has a character\n            if not targetPlayer.Character then\n                NexusLib:Notify({ Title = \"Spectate\", Message = targetPlayer.Name .. \" has no character!\", Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n                end\n                return\n            end\n            \n            local targetHrp = targetPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n            if not targetHrp then\n                NexusLib:Notify({ Title = \"Spectate\", Message = \"Cannot find HumanoidRootPart of \" .. targetPlayer.Name, Duration = 2 })\n                if NexusState.spectateToggle then\n                    NexusState.spectateToggle:Set(false)\n   ",
