"\x17\xD2\xFE\xAE\xB6.\x03`<0`@\xFB\x18\x19j1\xC2\xE4# k\x88oBe)VL8$bU(p0$y+*","                            local hrp = char and char:FindFirstChild(\"HumanoidRootPart\")\n                            local fishing = MainGui and MainGui:FindFirstChild(\"Fishing\")\n                            local inMinigame = fishing and fishing.Visible == true\n                            if cf and hrp and not inMinigame\n                                and (hrp.Position - cf.Position).Magnitude > 80\n                                and tick() - lastTp > 6 then\n                                lastTp = tick()\n                                hrp.CFrame = cf + Vector3.new(0, 6, 10)\n                            end\n                        end)\n                        task.wait(1.25)\n                    end\n                    tortoiseThread = nil\n                end)\n            end,\n        }\n        Cfg.register(\n            TortoiseSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Black Tortoise Bloodline\", fullConfig)),\n            \"Toggle\",\n            \"Auto Black Tortoise Bloodline\",\n            fullConfig\n        )\n    end\n    -- ===== FAVORITES =====\n    do\n        local FavSection = FarmingTab:CreateSection(\"Auto Favorite Fish\")\n        local allFishNames = {}\n        pcall(function()\n            local rarityModule = require(Info.FishingAreaRarity)\n            if type(rarityModule) == \"table\" then\n                for _, fishTable in pairs(rarityModule) do\n                    if type(fishTable) == \"table\" then\n                        for fishName in pairs(fishTable) do\n                            if type(fishName) == \"string\" and fishName ~= \"\" then\n                                table.insert(allFishNames, fishName)\n                            end\n                        end\n                    end\n                end\n            end\n        end)\n        local uniqueFish = {}\n        for _, name in ipairs(allFishNames) do uniqueFish[name] = true end\n        local fishOptions = {}\n        for name in pairs(uniqueFish) do table.insert(fishOptions, name) end\n        table.sort(fishOptions)\n\n        local fishDropdown = Cfg.register(FavSection:CreateMultiDropdown(Cfg.wrap(\"MultiDropdown\", \"Select fish to auto-favourite\", {\n            Name = \"Select fish to auto-favourite\",\n            Options = fishOptions,\n            Default = NexusState.favorites.selectedFish or {},\n            Callback = function(values) NexusState.favorites.selectedFish = values end\n        })), \"MultiDropdown\", \"Select fish to auto-favourite\", {\n            Name = \"Select fish to auto-favourite\",\n            Options = fishOptions,\n            Default = NexusState.favorites.selectedFish or {},\n            Callback = function(values) NexusState.favorites.selectedFish = values end\n        })\n\n        local autoFavToggle = Cfg.register(FavSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Favourite Fishes\", {\n            Name = \"Auto Favourite Fishes\",\n            Default = false,\n            Callback = function(value)\n                NexusState.favorites.autoEnabled = value\n                if value then\n                    if NexusState.favorites.thread then\n                        task.cancel(NexusState.favorites.thread)\n                        NexusState.favorites.thread = nil\n                    end\n                    NexusState.favorites.thread = task.spawn(function()\n                        local favoriteEvent = Events:FindFirstChild(\"FavoriteItem\")\n                        if not favoriteEvent then\n                            NexusLib:Notify({ Title = \"Auto Favourite\", Message = \"FavoriteItem remote not found!\", Duration = 3 })\n                            NexusState.favorites.autoEnabled = false\n                            if autoFavToggle and type(autoFavToggle.SetValue) == \"function\" then\n                                autoFavToggle:SetValue(false)\n         